using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Xml;
using System.Xml.Linq;

namespace CircuitoStudio {
 public static class XlsxWorkbook {
  static readonly XNamespace Main="http://schemas.openxmlformats.org/spreadsheetml/2006/main";
  static readonly XNamespace Rel="http://schemas.openxmlformats.org/officeDocument/2006/relationships";
  static readonly XNamespace PackageRel="http://schemas.openxmlformats.org/package/2006/relationships";
  static readonly XNamespace Content="http://schemas.openxmlformats.org/package/2006/content-types";
  static readonly HashSet<string> NumericHeaders=new HashSet<string>(new[]{"RatedA","BreakingKA","TripI2A","LetThroughA2s","MagneticA","RcdMilliA","SectionMm2","IzA","ResistanceOhmKm","ReactanceOhmKm"},StringComparer.Ordinal);
  static XDocument ReadXml(ZipArchive zip,string name){var e=zip.GetEntry(name);if(e==null)throw new InvalidDataException("Planilha XLSX incompleta: "+name);using(var s=e.Open()){var settings=new XmlReaderSettings{DtdProcessing=DtdProcessing.Prohibit,XmlResolver=null,MaxCharactersInDocument=32*1024*1024};using(var r=XmlReader.Create(s,settings))return XDocument.Load(r);}}
  static string SheetPath(string target){if(String.IsNullOrWhiteSpace(target))throw new InvalidDataException("Caminho da aba XLSX inválido.");target=target.Replace('\\','/');if(target.Contains(":"))throw new InvalidDataException("Caminho externo de aba XLSX não suportado.");string path=target.StartsWith("/")?target.TrimStart('/'):"xl/"+target;var parts=new List<string>();foreach(string part in path.Split('/')){if(part==""||part==".")continue;if(part==".."){if(parts.Count==0)throw new InvalidDataException("Caminho da aba XLSX inválido.");parts.RemoveAt(parts.Count-1);}else parts.Add(part);}path=String.Join("/",parts);if(!path.StartsWith("xl/",StringComparison.Ordinal))throw new InvalidDataException("A aba deve estar no diretório xl do pacote.");return path;}
  static int Column(string reference){int n=0;foreach(char c in reference){if(c<'A'||c>'Z')break;n=n*26+(c-'A'+1);}if(n<1||n>256)throw new InvalidDataException("Coluna XLSX inválida.");return n-1;}
  public static List<string[]> ReadRows(string path){
   var info=new FileInfo(path);if(!info.Exists||info.Length>32*1024*1024)throw new InvalidDataException("Arquivo XLSX inexistente ou maior que 32 MiB.");
   using(var fs=File.OpenRead(path))using(var zip=new ZipArchive(fs,ZipArchiveMode.Read,false)){
    long unpacked=zip.Entries.Sum(e=>e.Length);if(unpacked>64*1024*1024||zip.Entries.Count>2048)throw new InvalidDataException("Planilha XLSX excede o limite de leitura.");
    var workbook=ReadXml(zip,"xl/workbook.xml");var sheets=workbook.Root.Element(Main+"sheets");var first=sheets==null?null:sheets.Elements(Main+"sheet").FirstOrDefault();if(first==null)throw new InvalidDataException("A planilha não contém abas.");string rid=(string)first.Attribute(Rel+"id");if(String.IsNullOrEmpty(rid))throw new InvalidDataException("A primeira aba não tem relação válida.");
    var rels=ReadXml(zip,"xl/_rels/workbook.xml.rels");var relationship=rels.Root.Elements(PackageRel+"Relationship").FirstOrDefault(x=>(string)x.Attribute("Id")==rid);if(relationship==null||String.Equals((string)relationship.Attribute("TargetMode"),"External",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Não foi possível localizar a primeira aba.");string sheetPath=SheetPath((string)relationship.Attribute("Target"));
    var shared=new List<string>();var sharedEntry=zip.GetEntry("xl/sharedStrings.xml");if(sharedEntry!=null){var sharedDoc=ReadXml(zip,"xl/sharedStrings.xml");foreach(var si in sharedDoc.Root.Elements(Main+"si"))shared.Add(String.Concat(si.Descendants(Main+"t").Select(t=>t.Value)));}
    var sheet=ReadXml(zip,sheetPath);var data=sheet.Root.Element(Main+"sheetData");var rows=new List<string[]>();if(data==null)return rows;int rowNumber=0,headerWidth=0;
    foreach(var row in data.Elements(Main+"row")){if(++rowNumber>100000)throw new InvalidDataException("A planilha excede 100000 linhas.");var cells=new SortedDictionary<int,string>();int highest=-1;foreach(var cell in row.Elements(Main+"c")){string reference=(string)cell.Attribute("r")??"";int col=Column(reference);if(col>=64)throw new InvalidDataException("A planilha excede 64 colunas.");string type=(string)cell.Attribute("t")??"n",value="";if(type=="inlineStr"){var inline=cell.Element(Main+"is");if(inline!=null)value=String.Concat(inline.Descendants(Main+"t").Select(t=>t.Value));}else{var v=cell.Element(Main+"v");value=v==null?"":v.Value;if(type=="s"){int index;if(!Int32.TryParse(value,NumberStyles.None,CultureInfo.InvariantCulture,out index)||index<0||index>=shared.Count)throw new InvalidDataException("Índice de texto compartilhado inválido.");value=shared[index];}else if(type!="n"&&type!="str"&&type!="b"&&type!="e")throw new InvalidDataException("Tipo de célula XLSX não suportado: "+type);}
      if(type=="e")throw new InvalidDataException("A planilha contém célula com erro na linha "+rowNumber+".");if(value.Length>20000)throw new InvalidDataException("Célula excessivamente longa.");if(cells.ContainsKey(col))throw new InvalidDataException("Célula duplicada na linha "+rowNumber+".");cells[col]=value;highest=Math.Max(highest,col);}
     if(rows.Count==0)headerWidth=highest+1;var values=new string[Math.Max(highest+1,headerWidth)];for(int i=0;i<values.Length;i++)values[i]=cells.ContainsKey(i)?cells[i]:"";rows.Add(values);
    }return rows;
   }
  }
  static string ColumnName(int zeroBased){string name="";for(int n=zeroBased+1;n>0;n=(n-1)/26)name=(char)('A'+(n-1)%26)+name;return name;}
  static void Entry(ZipArchive zip,string name,XDocument xml){var e=zip.CreateEntry(name,CompressionLevel.Optimal);using(var s=e.Open())using(var w=XmlWriter.Create(s,new XmlWriterSettings{Encoding=new System.Text.UTF8Encoding(false),Indent=false,CloseOutput=false}))xml.Save(w);}
  public static void Write(string path,IEnumerable<string[]> rows){
   if(rows==null)throw new ArgumentNullException("rows");var list=rows.ToList();if(list.Count>100000)throw new InvalidDataException("A planilha excede 100000 linhas.");foreach(var row in list)if(row==null||row.Length>64||row.Any(x=>x!=null&&x.Length>20000))throw new InvalidDataException("Linha XLSX inválida ou excessivamente longa.");
   string full=Path.GetFullPath(path);Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var fs=File.Create(temp))using(var zip=new ZipArchive(fs,ZipArchiveMode.Create,false)){
    Entry(zip,"[Content_Types].xml",new XDocument(new XElement(Content+"Types",new XAttribute(XNamespace.Xmlns+"ct",Content),new XElement(Content+"Default",new XAttribute("Extension","rels"),new XAttribute("ContentType","application/vnd.openxmlformats-package.relationships+xml")),new XElement(Content+"Default",new XAttribute("Extension","xml"),new XAttribute("ContentType","application/xml")),new XElement(Content+"Override",new XAttribute("PartName","/xl/workbook.xml"),new XAttribute("ContentType","application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml")),new XElement(Content+"Override",new XAttribute("PartName","/xl/worksheets/sheet1.xml"),new XAttribute("ContentType","application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml")))));
    Entry(zip,"_rels/.rels",new XDocument(new XElement(PackageRel+"Relationships",new XAttribute(XNamespace.Xmlns+"r",PackageRel),new XElement(PackageRel+"Relationship",new XAttribute("Id","rId1"),new XAttribute("Type","http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument"),new XAttribute("Target","xl/workbook.xml")))));
    Entry(zip,"xl/workbook.xml",new XDocument(new XElement(Main+"workbook",new XAttribute(XNamespace.Xmlns+"r",Rel),new XElement(Main+"sheets",new XElement(Main+"sheet",new XAttribute("name","Dados"),new XAttribute("sheetId","1"),new XAttribute(Rel+"id","rId1"))))));
    Entry(zip,"xl/_rels/workbook.xml.rels",new XDocument(new XElement(PackageRel+"Relationships",new XElement(PackageRel+"Relationship",new XAttribute("Id","rId1"),new XAttribute("Type","http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet"),new XAttribute("Target","worksheets/sheet1.xml")))));
    XNamespace xml=XNamespace.Xml;var sheetRows=new List<XElement>();for(int ri=0;ri<list.Count;ri++){var cells=new List<XElement>();for(int ci=0;ci<list[ri].Length;ci++){string value=list[ri][ci]??"";string reference=ColumnName(ci)+(ri+1).ToString(CultureInfo.InvariantCulture);bool numeric=ri>0&&list[0].Length>ci&&NumericHeaders.Contains(list[0][ci]);double number;if(numeric&&value.Length>0){if(!Double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out number)||Double.IsNaN(number)||Double.IsInfinity(number))throw new InvalidDataException("Valor numérico XLSX inválido na coluna "+list[0][ci]+".");cells.Add(new XElement(Main+"c",new XAttribute("r",reference),new XElement(Main+"v",number.ToString("R",CultureInfo.InvariantCulture))));}else cells.Add(new XElement(Main+"c",new XAttribute("r",reference),new XAttribute("t","inlineStr"),new XElement(Main+"is",new XElement(Main+"t",new XAttribute(xml+"space","preserve"),value))));}sheetRows.Add(new XElement(Main+"row",new XAttribute("r",ri+1),cells));}Entry(zip,"xl/worksheets/sheet1.xml",new XDocument(new XElement(Main+"worksheet",new XElement(Main+"sheetData",sheetRows))));
   }if(File.Exists(full))File.Replace(temp,full,null);else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}
  }
 }
}
